import os
import json
import hmac
import hashlib
import subprocess
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

SECRET_KEY = os.environ.get('WEBHOOK_SECRET', 'default-secret-key')
DEPLOY_DIR = os.environ.get('DEPLOY_DIR', '/opt/deployments')
ALLOWED_REPOS = os.environ.get('ALLOWED_REPOS', 'myorg/myapp').split(',')

def verify_signature(payload_body, signature):
    """Verify GitHub webhook signature"""
    if not signature:
        return False
    expected = 'sha256=' + hmac.new(
        SECRET_KEY.encode(), payload_body, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/webhook/deploy', methods=['POST'])
def handle_deploy():
    """Handle deployment webhook from CI/CD pipeline"""
    signature = request.headers.get('X-Hub-Signature-256')

    # Signature verification - but SECRET_KEY might be weak
    if not verify_signature(request.data, signature):
        abort(403, 'Invalid signature')

    payload = request.get_json()
    if not payload:
        abort(400, 'Missing payload')

    repo = payload.get('repository', {}).get('full_name', '')
    ref = payload.get('ref', '')

    # Repo allowlist check
    if repo not in ALLOWED_REPOS:
        abort(403, f'Repository {repo} not allowed')

    # Branch validation - only deploy from main
    if ref != 'refs/heads/main':
        abort(400, 'Only main branch deployments allowed')

    # Extract deployment artifact URL
    artifact_url = payload.get('deployment', {}).get('payload', {}).get('artifact_url', '')

    if not artifact_url:
        abort(400, 'No artifact URL provided')

    # VULNERABILITY: artifact_url is used directly in shell command
    # An attacker who can forge/bypass the webhook signature can inject commands
    deploy_script = f"""
#!/bin/bash
set -e
cd {DEPLOY_DIR}
curl -sSL -o artifact.tar.gz "{artifact_url}"
tar xzf artifact.tar.gz
./run_migrations.sh
systemctl reload myapp
"""

    script_path = '/tmp/deploy.sh'
    with open(script_path, 'w') as f:
        f.write(deploy_script)
    os.chmod(script_path, 0o755)

    result = subprocess.run(
        ['/bin/bash', script_path],
        capture_output=True,
        text=True,
        timeout=300
    )

    if result.returncode != 0:
        return jsonify({
            'status': 'failed',
            'error': result.stderr[:500]
        }), 500

    return jsonify({
        'status': 'deployed',
        'repo': repo,
        'ref': ref
    })

@app.route('/webhook/rollback', methods=['POST'])
def handle_rollback():
    """Emergency rollback endpoint"""
    signature = request.headers.get('X-Hub-Signature-256')
    if not verify_signature(request.data, signature):
        abort(403, 'Invalid signature')

    payload = request.get_json()
    version = payload.get('version', 'previous')

    # Also vulnerable to injection via version parameter
    cmd = f'cd {DEPLOY_DIR} && git checkout {version} && systemctl reload myapp'
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)

    return jsonify({'status': 'rolled_back', 'version': version})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
